    function grafico_barra(data){
      const margin = ({top: 30, right: 20, bottom: 40, left: 50})
      const width = 500
      const height = 800



    // Lista dos subgrupos (modelos)
    const subgroups = [...new Set(data.map(d =&gt; d.modelo))].sort()

    // Lista dos grupos (faixas etárias) - mantendo a ordem original
    const groups = [...new Set(data.map(d =&gt; d.faixa))]

    // Criar o SVG
    const svg = d3.create("svg")
      .attr("width", width + margin.left + margin.right)
      .attr("height", height + margin.top + margin.bottom)
      .attr("style", "height: auto; height: intrinsic; font: 10px sans-serif;")
      .style("-webkit-tap-highlight-color", "transparent")

    const g = svg.append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`)

    // Escalas
    // Escala Y para as faixas etárias (grupos)
    const y = d3.scaleBand()
      .domain(groups)
      .range([0, height])
      .padding(0.2)

    // Escala X para os valores
    const x = d3.scaleLinear()
      .domain([d3.min(data, d =&gt; d.valor)-0.5, d3.max(data, d =&gt; d.valor)])
      .range([0, width])

    // Escala Y para subgrupos (posição das barras dentro de cada faixa etária)
    const ySubgroup = d3.scaleBand()
      .domain(subgroups)
      .range([0, y.bandwidth()])
      .padding(0.05)

    // Escala de cores
    const color = d3.scaleOrdinal()
      .domain(["ARIMA+ETS", "Lee-Carter", "Lee-Miller", "MLP-Shallow"]) // Ordem explícita
      .range(['#404788FF', '#238A8DFF', '#55C667FF', '#FDE725FF'])

    // Adicionar eixo X
    g.append("g")
      .attr("transform", `translate(0,${height})`)
      .call(d3.axisBottom(x))

    // Adicionar eixo Y
    g.append("g")
      .call(d3.axisLeft(y))

    // Criar as barras
    g.append("g")
      .selectAll("g")
      .data(groups)
      .enter()
      .append("g")
      .attr("transform", d =&gt; `translate(0,${y(d)})`)
      .selectAll("rect")
      .data(faixa =&gt; {
        return subgroups.map(modelo =&gt; {
          const dataPoint = data.find(d =&gt; d.faixa === faixa && d.modelo === modelo);
          return {
            modelo: modelo,
            valor: dataPoint ? dataPoint.valor : 0,
            faixa: faixa
          };
        });
      })
      .enter()
      .append("rect")
      .attr("x", 0)
      .attr("y", d =&gt; ySubgroup(d.modelo))
      .attr("width", d =&gt; x(d.valor))
      .attr("height", ySubgroup.bandwidth())
      .attr("fill", d =&gt; color(d.modelo))

    // Adicionar rótulos dos eixos
    g.append("text")
      .attr("transform", "rotate(-90)")
      .attr("y", 0 - margin.left)
      .attr("x", 0 - (height / 2))
      .attr("dy", "1em")
      .style("text-anchor", "middle")
      .text("Faixa Etária")

    g.append("text")
