      .style("text-anchor", "middle")
      .text("Valor em log")

    const legendItemSpacing = 110; // Espaço que cada item da legenda ocupa
    const totalLegendWidth = subgroups.length * legendItemSpacing;
    const legendStartX = (width / 2) - (totalLegendWidth / 2);

    const legend = g.append("g")
